# Code generated by AI.
from pathlib import Path

import pandas as pd
import numpy as np
import pytest

from generate_synthetic_dataset import (
    SyntheticVCFGenerator,
    generate_gene_counts,
    make_reference_panel,
)


FIXTURE_DIR = Path(__file__).resolve().parent / "fixtures" / "synthetic"


def read_tsv(name: str) -> pd.DataFrame:
    return pd.read_csv(FIXTURE_DIR / name, sep="\t")


def test_allele_counts_schema():
    df = read_tsv("allele_counts.tsv")
    required = {
        "Chr",
        "Pos",
        "reference_tumor_count",
        "alternative_tumor_count",
        "Type",
        "Chr_Allele",
        "Alternative_Allele",
    }
    assert required.issubset(df.columns)
    assert (df["Type"] == "SNP").all()
    assert len(df) > 0


def test_markers_overlap_with_allele_counts():
    markers = read_tsv("markerslist.tsv")
    allele_counts = read_tsv("allele_counts.tsv")
    marker_pairs = set(zip(markers["Chr"], markers["Pos"]))
    allele_pairs = set(zip(allele_counts["Chr"], allele_counts["Pos"]))
    assert marker_pairs.issubset(allele_pairs)


def test_gene_reference_panel_merge():
    gene_counts = read_tsv("gene_counts.tsv")
    reference = read_tsv("reference_panel.tsv")
    merged = gene_counts.merge(
        reference[["geneID", "arm", "refcpm", "Pos"]],
        on="geneID",
        how="inner",
        suffixes=("_gene", "_ref"),
    )
    assert not merged.empty
    assert {"geneID", "count", "refcpm"}.issubset(merged.columns)
    assert merged["geneID"].nunique() == len(gene_counts)


def test_generator_emits_vcf_ready_rows():
    generator = SyntheticVCFGenerator(seed=7)
    rows = generator.generate_rows(
        {"chr1": [10, 20, 30]},
        {"chr1": [(15, 25, "A", 0.35)]},
    )

    assert len(rows) == 3
    assert {row["CNV"] for row in rows} == {"AB", "A"}
    assert all(len(row["REF"]) == len(row["ALT"]) == 1 for row in rows)
    assert all(row["reference_tumor_count"] + row["alternative_tumor_count"] > 0 for row in rows)


def test_generator_rejects_invalid_genomic_parameters():
    generator = SyntheticVCFGenerator(seed=7)

    with pytest.raises(ValueError):
        generator.genomic_params(-0.1, "A")
    with pytest.raises(ValueError):
        generator.genomic_params(0.35, "unsupported")


def test_rna_generation_uses_reference_range_and_cnv_scaling():
    chromosome_sizes = {"chr1": 1000}
    rng = np.random.default_rng(11)
    reference = make_reference_panel(chromosome_sizes, 20, rng)
    generator = SyntheticVCFGenerator(seed=11)
    counts = generate_gene_counts(
        reference,
        {"chr1": [(1, 500, "A", 0.35)]},
        generator,
        np.random.default_rng(12),
    )

    assert len(reference) == len(counts) == 20
    assert reference["refcpm"].between(10, 10**7).all()
    assert counts["count"].map(np.isfinite).all()
